//! Holds the [`SendableChooser`] type, which can be sent to a dashboard to let
//! the operator choose between some options.
//!
//! Other sendable dialogs are planned in the future.

use std::collections::HashMap;

use crate::ffi;

/// Helps create values that can be put in to a [SendableChooser]. Maps an enum
/// value to a name, and optionally a value.
///
/// Four things are generated by this macro:
///
/// * A basic enum, with each option.
/// * A const function called `name` that converts an option to it's name.
/// * A const array called `ALL` that holds every item in the enum.
/// * Optionally, a function called `value` that converts an option to it's
///   value.
/// * Optionally, a const function called `value that converts an option to it's
///   value. You cannot have both a const and a non-const function.
///
/// ## Examples
///
/// Basic usage:
///
/// ```
/// use robot_rust::prelude::*;
///
/// chooser_enum! {
///     enum Value {
///         None("None"),
///         Car("Car"),
///         Hat("Hat"),
///     }
/// }
/// ```
///
/// With a value:
///
/// ```
/// use robot_rust::prelude::*;
///
/// chooser_enum! {
///     enum Cart<Vec<&'static str>> {
///         Empty("Empty", vec![]),
///         Milk("Milk", vec!["Milk"]),
///         MilkAndCrackers("Milk & Crakcers", vec!["Milk", "Crackers"]),
///     }
/// }
/// ```
///
/// With a const value:
///
/// ```
/// use robot_rust::prelude::*;
///
/// chooser_enum! {
///     enum Number<const u32> {
///         Zero("Zero", 0),
///         One("One", 1),
///         Ten("Ten", 10),
///     }
/// }
/// ```
#[macro_export]
macro_rules! chooser_enum {
    (
        enum $Chooser:ident$(<$Type:ty>)? $(const <$ConstType:ty>)? {
            $(
                $Name:ident($name:expr$(, $value:expr)? $(, $const_value:expr)?),
            )+
        }
    ) => {
        pub enum $Chooser {
            $(
                $Name,
            )+
        }

        impl $Chooser {
            pub const fn name(&self) -> &'static str {
                match *self {
                    $(
                        Self::$name => $name,
                    )+
                }
            }

            $(
                pub fn value(&self) -> $Type {
                    match *self {
                        $(
                            Self::$name => $value
                        )+
                    }
                }
            )?

            $(
                pub const fn value(&self) -> $ConstType {
                    match *self {
                        $(
                            Self::$name => $const_value
                        )+
                    }
                }
            )?

            pub const ALL: &'static [Self] = [
                $(
                    Self::$Name,
                )+
            ];
        }
    };
}

/// Send a selection of options to the dashboard.
///
/// Options are strings that are mapped to a type `T`.
///
/// You must call [SendableChooser::publish] to send the chooser to the
/// dashboard.
///
/// ## Type parameter
///
/// * T: The data each name will represent. If you don't want to represent any
///   data, you can just set it to `()`, and use the
///   [SendableChooser::get_selected_name] function.
///
/// ## Examples
///
/// ```
/// use robot_rust::prelude::*;
///
/// chooser_enum! {
///     enum AutoMode {
///         None("None"),
///         Left("Left"),
///         Right("Right"),
///     }
/// }
///
/// struct Dashboard {
///     autos: SendableChooser<AutoMode>,
/// }
///
/// impl Dashboard {
///     fn new() -> Self {
///         let mut autos = SendableChooser::new();
///         autos.set_default(AutoMode::None::name(), AutoMode::None);
///         for &mode in AutoMode::ALL {
///             autos.add_option(mode.name, mode);
///         }
///
///         Self { autos }
///     }
/// }
/// ```
///
/// ## Bound code
///
/// This type contains bound code, safety of some functions is not guaranteed.
pub struct SendableChooser<T> {
    handle: *mut ffi::ChooserHandle,
    options: HashMap<String, T>,
    default: Option<String>,
}

impl<T> SendableChooser<T> {
    /// Creates a new chooser with no options.
    pub fn new() -> Self {
        Self {
            handle: ffi::chooser_create(),
            options: HashMap::new(),
            default: None,
        }
    }

    /// Add an option to the chooser, with a name and value.
    pub fn add_option(&mut self, name: &str, value: T) {
        unsafe {
            ffi::chooser_add_option(self.handle, name);
        }

        self.options.insert(name.to_string(), value);
    }

    /// Set the default option for the chooser.
    pub fn set_default(&mut self, name: &str, value: T) {
        self.add_option(name, value);
        self.default = Some(name.to_string());
    }

    /// Publish the chooser to the dashboard.
    pub fn publish(&self, name: &str) {
        unsafe {
            ffi::chooser_publish(self.handle, name);
        }
    }

    /// Get the value of the currently selected option.
    pub fn get_selected(&self) -> Option<&T> {
        self.options.get(&self.get_selected_name())
    }

    /// Get the name of the currently selected option.
    pub fn get_selected_name(&self) -> String {
        unsafe { ffi::chooser_get_selected(self.handle) }.to_string()
    }
}

impl<T> Drop for SendableChooser<T> {
    fn drop(&mut self) {
        unsafe {
            ffi::chooser_destroy(self.handle);
        }
    }
}
